import re

from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import CommandFailure, ParsingDone


class Objcli(GenericUnixCommand):
    """Objcli command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Objcli command enable or disable SecurityOverEth.

        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        :param connection: moler connection to device, terminal when command is executed.
        :param options: argument of main command with flag true or asnything else
        """
        super(Objcli, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.options = options
        self.current_ret["RESULT"] = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "/opt/trs/bin/objcli"
        cmd = f"{cmd} {self.options}"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Summary line.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_disabled_header(line)

            except ParsingDone:
                pass
        return super(Objcli, self).on_new_line(line, is_full_line)

    # /opt/trs/bin/objcli SecurityOverEth false
    _re_check_disable = re.compile(r"^.opt.+(?P<ERROR>SecurityOverEth\s\w+)")

    def _parse_disabled_header(self, line):
        if self._regex_helper.search_compiled(Objcli._re_check_disable, line):
            self.set_exception(CommandFailure(self, f"ERROR: Entered {self._regex_helper.group('ERROR')} instead of 'true'"))

            raise ParsingDone


